1	// FlashAttention-2-style BF16 forward kernel for sm_86 (RTX 3090 Ti).
2	// - wmma 16x16x16 tensor-core matmuls (mma.sync.m16n8k16 under the hood)
3	// - cp.async double-buffered K/V tiles; padded row stride (136 bf16) makes
4	//   ldmatrix reads conflict-free
5	// - online softmax; softmaxed scores are staged as bf16 through a small
6	//   per-warp shared tile (true row/col layout) before the PV matmul, because
7	//   the m16n16k16 accumulator layout differs from the matrix_a layout.
8	#include <torch/extension.h>
9	#include <ATen/cuda/CUDAContext.h>
10	#include <c10/cuda/CUDAGuard.h>
11	#include <cuda_bf16.h>
12	#include <mma.h>
13	#include <math.h>
14	
15	namespace {
16	
17	using namespace nvcuda;
18	
19	constexpr int BLOCK_M = 64;    // query rows per block
20	constexpr int BLOCK_N = 64;    // kv rows per tile
21	constexpr int HEAD_DIM = 128;
22	constexpr int NUM_WARPS = 4;
23	constexpr int NUM_THREADS = NUM_WARPS * 32;
24	constexpr int PADDED_D = HEAD_DIM + 8;        // 16 B/row padding
25	constexpr int P_COLS = BLOCK_N + 8;           // P tile cols (72) -> conflict-free bf16 smem writes
26	constexpr int TILE_ELEMS = BLOCK_N * PADDED_D;  // per K or V tile (bf16)
27	constexpr int O_ELEMS = BLOCK_M * PADDED_D;     // O staging (reuses Q buffer)
28	constexpr int P_SMEM = NUM_WARPS * 16 * P_COLS * 2;  // bf16 P staging for PV (9,216 B)
29	constexpr int SMEM_BYTES = 4 * TILE_ELEMS * 2 + O_ELEMS * 2 + P_SMEM;  // 96,256 B
30	
31	__device__ __forceinline__ void cp_async16(void* smem, const void* gmem) {
32	    uint32_t s = static_cast<uint32_t>(__cvta_generic_to_shared(smem));
33	    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" :: "r"(s), "l"(gmem));
34	}
35	__device__ __forceinline__ void cp_async_commit() {
36	    asm volatile("cp.async.commit_group;\n");
37	}
38	template<int N>
39	__device__ __forceinline__ void cp_async_wait() {
40	    asm volatile("cp.async.wait_group %0;\n" :: "n"(N));
41	}
42	
43	// Copy a BLOCK_N x HEAD_DIM tile from gmem (rows kv0..) to padded shared,
44	// zero-filling rows past seq_len. Also used to stage Q (kv0 = query row base).
45	__device__ __forceinline__ void load_tile(
46	    const __nv_bfloat16* __restrict__ src, __nv_bfloat16* __restrict__ dst,
47	    int row0, int seq_len)
48	{
49	    constexpr int CHUNKS = BLOCK_N * HEAD_DIM / 8;  // 16B chunks
50	#pragma unroll
51	    for (int i = threadIdx.x; i < CHUNKS; i += NUM_THREADS) {
52	        const int row = i / (HEAD_DIM / 8);
53	        const int col8 = i % (HEAD_DIM / 8);
54	        const int grow = row0 + row;
55	        __nv_bfloat16* s = dst + row * PADDED_D + col8 * 8;
56	        if (grow < seq_len) {
57	            cp_async16(s, src + (long long)grow * HEAD_DIM + col8 * 8);
58	        } else {
59	            *reinterpret_cast<uint4*>(s) = make_uint4(0, 0, 0, 0);
60	        }
61	    }
62	}
63	
64	__device__ __forceinline__ float warp_max4(float v) {
65	#pragma unroll
66	    for (int off = 1; off < 4; off <<= 1)
67	        v = fmaxf(v, __shfl_xor_sync(0xffffffffu, v, off));
68	    return v;
69	}
70	__device__ __forceinline__ float warp_sum4(float v) {
71	#pragma unroll
72	    for (int off = 1; off < 4; off <<= 1)
73	        v += __shfl_xor_sync(0xffffffffu, v, off);
74	    return v;
75	}
76	
77	__global__ void __launch_bounds__(NUM_THREADS, 1)
78	attention_fwd_kernel(const __nv_bfloat16* __restrict__ q,
79	                     const __nv_bfloat16* __restrict__ k,
80	                     const __nv_bfloat16* __restrict__ v,
81	                     __nv_bfloat16* __restrict__ out,
82	                     int seq_len, float scale, bool causal,
83	                     int num_heads, int kv_heads)
84	{
85	    extern __shared__ char smem[];
86	    __nv_bfloat16* sK0 = reinterpret_cast<__nv_bfloat16*>(smem);
87	    __nv_bfloat16* sV0 = sK0 + TILE_ELEMS;
88	    __nv_bfloat16* sK1 = sV0 + TILE_ELEMS;
89	    __nv_bfloat16* sV1 = sK1 + TILE_ELEMS;
90	    __nv_bfloat16* sP = sV1 + TILE_ELEMS;      // bf16 P staging for PV matmul
91

1	#include <torch/extension.h>
2	
3	torch::Tensor attention_forward(torch::Tensor q, torch::Tensor k,
4	                                torch::Tensor v, bool causal);
5	
6	PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
7	    m.def("attention_forward", &attention_forward,
8	          "Attention forward (BF16, [B,H,S,D], D=128)",
9	          py::arg("q"), py::arg("k"), py::arg("v"), py::arg("causal"));
10	}

